using UnityEngine;
using UnityEditor;
using UnityEngine.InputSystem;
using UnityEngine.InputSystem.LowLevel;
using System;
using System.IO;
using ConRoi.Investigation.V36.R107;

namespace Unity.AI.Assistant.Agent.Dynamic.Extension.Editor
{
    internal class CommandScript : IRunCommand
    {
        public void Execute(ExecutionResult r)
        {
            var s = UnityEngine.Object.FindFirstObjectByType<InvestigationSession>();
            if (!s.Has("phone") || !s.data.firstNotesReviewed || s.Page != "inspect")
                throw new Exception("Complete controller phone route first");
            var kb = InputSystem.AddDevice<Keyboard>();
            kb.MakeCurrent();
            int step = 0;
            double next = EditorApplication.timeSinceStartup + 1;
            EditorApplication.CallbackFunction f = null;
            f = () =>
            {
                if (EditorApplication.timeSinceStartup < next)
                    return;
                next = EditorApplication.timeSinceStartup + 1.5;
                switch (step++)
                {
                    case 0:
                        InputSystem.QueueStateEvent(kb, new KeyboardState(Key.F5));
                        break;
                    case 1:
                        InputSystem.QueueStateEvent(kb, new KeyboardState());
                        if (!File.Exists(s.SavePath))
                            throw new Exception("Phone save absent");
                        File.WriteAllText("Test/Output/CleanCheckout/pre-nav-live.json", JsonUtility.ToJson(s.data, true));
                        File.WriteAllText("Test/Output/CleanCheckout/pre-nav-profile.txt", s.SavePath);
                        s.SaveDirectoryOverride = Path.GetFullPath("Test/PlaytestProfiles/NavFixture_a789222_20261107");
                        if (File.Exists(s.SavePath))
                            throw new Exception("Fixture profile already used");
                        s.Acquire("letter");
                        File.WriteAllText("Test/Output/CleanCheckout/nav-fixture-disclosure.txt", "API fixture: letter acquired only to expose cipher navigation. Floor and phone previously acquired by controller/E; no API OpenPage/Observe/Save/Load. Separate profile=" + s.SavePath);
                        InputSystem.QueueStateEvent(kb, new KeyboardState(Key.R));
                        break;
                    case 2:
                        InputSystem.QueueStateEvent(kb, new KeyboardState());
                        break;
                    case 3:
                        InputSystem.QueueStateEvent(kb, new KeyboardState(Key.P));
                        break;
                    case 4:
                        InputSystem.QueueStateEvent(kb, new KeyboardState());
                        break;
                    default:
                        ScreenCapture.CaptureScreenshot("Test/Output/CleanCheckout/nav-dossier-1080.png");
                        File.WriteAllText("Test/Output/CleanCheckout/nav-setup.txt", "page=" + s.Page + " evidence=" + s.InspectionCount + " mapping=" + s.data.mapping.Count + " finalized=" + s.data.finalized);
                        InputSystem.RemoveDevice(kb);
                        EditorApplication.update -= f;
                        break;
                }
            };
            EditorApplication.update += f;
            r.Log("Queue profile-isolated navigation fixture; only letter seeded via API, UI pages via keys");
        }
    }
}

